-- Frame Codex roster.
-- Import this after sql/schema.sql.
-- Importing it again refills the catalog. User accounts stay. Favorites are cleared
-- because the Warframe rows are replaced.

SET NAMES utf8mb4;

USE frame_codex;
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM favorites;
DELETE FROM abilities;
DELETE FROM warframe_roles;
DELETE FROM warframes;
DELETE FROM roles;
SET FOREIGN_KEY_CHECKS = 1;


SET FOREIGN_KEY_CHECKS = 0;
SET FOREIGN_KEY_CHECKS = 1;



-- Primes and Protoframes use the same roles and passive text as the linked Warframe.
SELECT child.id, parent_roles.role_id
FROM warframes AS child
INNER JOIN warframe_roles AS parent_roles ON parent_roles.warframe_id = child.related_id
WHERE child.category IN ('prime', 'protoframe');

UPDATE warframes AS child
INNER JOIN warframes AS parent ON parent.id = child.related_id
SET child.passive_name = parent.passive_name,
    child.passive_summary = parent.passive_summary
WHERE child.category IN ('prime', 'protoframe');
