(1, 'Crowd Control'),
(2, 'Damage'),
(3, 'Stealth'),
(4, 'Support'),
(5, 'Survival');
INSERT INTO warframes (id, name, slug, category, related_id, summary, passive_name, passive_summary, health, shields, armor, energy, accent) VALUES
(1, 'Ash', 'ash', 'warframe', NULL, 'A stealth attacker who marks targets and finishes them with bleeding cuts.', 'Bleeding Edge', 'Slash effects from Ash deal more damage, and finishers cut enemies open.', 555, 370, 105, 150, '#8d8f98'),
(2, 'Atlas', 'atlas', 'warframe', NULL, 'A stone brawler who petrifies enemies and builds armor from the rubble.', 'Rubble', 'Atlas cannot be knocked down on the ground, and petrified enemies drop rubble that raises his armor.', 370, 370, 475, 225, '#c4a574'),
(3, 'Banshee', 'banshee', 'warframe', NULL, 'A sound fighter who exposes weak points and locks down a room.', 'Silent Arms', 'Banshee and her robotic companion fire without making weapon noise.', 370, 370, 105, 225, '#7ec8c3'),
(4, 'Baruuk', 'baruuk', 'warframe', NULL, 'A restrained monk whose fists grow stronger as his patience runs out.', 'Restraint', 'Dodging danger and disarming foes lowers his restraint, and his strikes hit harder as it falls.', 280, 370, 185, 300, '#e6d3a3'),
(5, 'Caliban', 'caliban', 'warframe', NULL, 'A sentient-touched fighter who lifts enemies and calls allies to his side.', 'Shield Link', 'Caliban and nearby allies recharge shields faster.', 370, 650, 290, 190, '#6ea8d8'),
(6, 'Chroma', 'chroma', 'warframe', NULL, 'A dragon knight whose element follows his energy color.', 'Elemental Alignment', 'Energy color chooses his element, and he resists that element more easily.', 370, 370, 370, 225, '#e07a3d'),
(7, 'Citrine', 'citrine', 'warframe', NULL, 'A crystal supporter who hardens allies and turns damage into healing gems.', 'Gem Heart', 'Citrine heals nearby allies. Picking up health orbs raises that healing.', 500, 370, 265, 180, '#e2b340'),
(8, 'Cyte-09', 'cyte-09', 'warframe', NULL, 'A sniper who plans the shot, then disappears after it lands.', 'Weak Point', 'Shots that hit a weak point can punch through toward another enemy.', 325, 235, 150, 230, '#9aa3ad'),
(9, 'Dagath', 'dagath', 'warframe', NULL, 'A headless rider who dooms enemies and calls a spectral horse.', 'Grave Pace', 'Her abilities slow enemies. A killing blow can leave her as a spirit long enough to strike back.', 666, 250, 125, 225, '#c45c7a'),
(10, 'Dante', 'dante', 'warframe', NULL, 'A scholar who writes light and dark verses, then spends them on a final spell.', 'Noctua', 'Light Verse and Dark Verse fill pages. Final Verse spends those pages.', 390, 240, 145, 270, '#d7c4a3'),
(11, 'Ember', 'ember', 'warframe', NULL, 'A fire caster whose heat builds until the room is burning.', 'Immolation Meter', 'Dealing heat fills a meter that makes her abilities stronger while Immolation is active.', 370, 370, 135, 225, '#e25822'),
(12, 'Equinox', 'equinox', 'warframe', NULL, 'Two forms in one Warframe: a calming night side and a violent day side.', 'Equilibrium', 'Health orbs grant extra energy in day form. Energy orbs grant extra health in night form.', 370, 370, 135, 225, '#c9a0b8'),
(13, 'Excalibur', 'excalibur', 'warframe', NULL, 'A swordsman who dashes in, blinds the line, and finishes with an exalted blade.', 'Swordsmanship', 'Swords deal extra damage and have a chance to make enemies bleed.', 370, 370, 240, 150, '#3d7eff'),
(14, 'Excalibur Umbra', 'excalibur-umbra', 'warframe', NULL, 'A sentient Excalibur who keeps fighting even when the Operator steps out.', 'Sentient Blade', 'He shares Excalibur''s sword bonus, and he acts on his own while the Operator is away.', 370, 370, 315, 225, '#6b5344'),
(15, 'Follie', 'follie', 'warframe', NULL, 'An ink artist who drops through frames, sketches tools, and ties enemies to balloons.', 'Inkblot', 'Her abilities coat enemies in ink that slows them. Ink-covered foes can burst into orbs when they die.', 585, 325, 325, 225, '#3a342f'),
(16, 'Frost', 'frost', 'warframe', NULL, 'A defender who freezes crowds and holds ground inside a snow globe.', 'Shatter', 'Frozen enemies take extra damage when they are broken apart.', 370, 555, 315, 150, '#8ec9ef'),
(17, 'Gara', 'gara', 'warframe', NULL, 'A glass guardian who wraps allies in splinters and walls off a fight.', 'Glass Skin', 'Attackers who strike her glass have a chance to be blinded.', 370, 370, 160, 225, '#d5ece4'),
(18, 'Garuda', 'garuda', 'warframe', NULL, 'A blood hunter who spends health, builds energy, and marks prey for bleeding talons.', 'Blood Price', 'Her claws hit harder as her health drops, and her attacks make enemies bleed.', 370, 370, 315, 240, '#c4392a'),
(19, 'Gauss', 'gauss', 'warframe', NULL, 'A runner who fills a battery by moving and spends it on speed and heat.', 'Battery', 'Sprinting and his abilities fill a battery that makes the rest of his kit stronger.', 370, 555, 185, 225, '#e85d4c'),
(20, 'Grendel', 'grendel', 'warframe', NULL, 'A glutton who eats enemies and turns the meal into armor, bile, or a rolling attack.', 'Feast Gut', 'Enemies in his gut feed his other abilities, and he is hard to knock over.', 1295, 95, 370, 225, '#6f8f4e'),
(21, 'Gyre', 'gyre', 'warframe', NULL, 'An electric coil who chains critical hits through a crowd.', 'Static Critical', 'Critical hits build a charge that raises her critical chance while her kit is spinning.', 370, 650, 105, 240, '#7d8cff'),
(22, 'Harrow', 'harrow', 'warframe', NULL, 'A chaplain who chains enemies, then turns the squad''s fire into healing and energy.', 'Headhunter', 'Headshots fill a gauge. His next cast can spend it to restore energy and shields.', 370, 555, 185, 150, '#f2efe6'),
(23, 'Hildryn', 'hildryn', 'warframe', NULL, 'A shield tank who spends shields instead of energy and strips enemy defenses.', 'Shield Well', 'Hildryn has no energy pool. Abilities spend shields, and extra shields raise her strength.', 280, 1780, 315, 0, '#f0d78c'),
(24, 'Hydroid', 'hydroid', 'warframe', NULL, 'A pirate of the tide who drowns armor and drags enemies under.', 'Plunderer', 'Corroded enemies make his watery attacks hit harder, and his victims can drop extra loot.', 370, 465, 240, 190, '#3e7c78'),
(25, 'Inaros', 'inaros', 'warframe', NULL, 'A desert king with a deep health pool and sand that blinds, devours, and armors him.', 'Sarcophagus', 'Finishers heal him. If he falls, his sarcophagus can bring him back.', 2310, 0, 240, 150, '#d4b483'),
(26, 'Ivara', 'ivara', 'warframe', NULL, 'A hunter who picks the right arrow, walks unseen, and fires an exalted bow.', 'Quiet Step', 'Ivara moves more quietly, and Prowl lets her steal from enemies she passes.', 280, 370, 105, 265, '#7d9a6a'),
(27, 'Jade', 'jade', 'warframe', NULL, 'An aerial supporter whose light heals allies and marks enemies for a final blast.', 'Angelic Care', 'Judgments on the field make her songs and her final explosion stronger.', 465, 550, 135, 200, '#8fbf9a'),
(28, 'Khora', 'khora', 'warframe', NULL, 'A whip fighter paired with the kavat Venari.', 'Venari', 'Venari fights beside Khora and can be called back if she falls.', 465, 370, 290, 190, '#c9845a'),
(29, 'Koumei', 'koumei', 'warframe', NULL, 'A dice maiden who weaves fate, offers challenges, and puppets enemies on threads.', 'Loaded Dice', 'On a timer, one of her weapons gains random status effects. Her casts also roll dice.', 444, 222, 444, 222, '#e7b3c8'),
(30, 'Kullervo', 'kullervo', 'warframe', NULL, 'A betrayed swordsman who teleports into heavy melee and spreads the pain.', 'Melee Critical', 'Melee hits have a much higher critical chance. Ranged weapons give some of that up.', 1205, 0, 650, 225, '#8e2f2f'),
(31, 'Lavos', 'lavos', 'warframe', NULL, 'An alchemist who mixes elements and casts from cooldowns instead of energy.', 'Transmutation', 'Hold an ability to imbue the next cast with that element. Orbs shorten his cooldowns.', 740, 370, 675, 0, '#6a8f5b'),
(32, 'Limbo', 'limbo', 'warframe', NULL, 'A rift magician who steps between planes and freezes anyone caught on his side.', 'Rift Walk', 'Dodge rolls Limbo into the Rift, where most attacks cannot touch him.', 370, 280, 105, 225, '#2f5fbf'),
(33, 'Loki', 'loki', 'warframe', NULL, 'A trickster who leaves a decoy, vanishes, and strips guns out of enemy hands.', 'Long Cling', 'Loki clings to walls longer and is harder for enemies to notice.', 280, 280, 105, 225, '#8fce86'),
(34, 'Mag', 'mag', 'warframe', NULL, 'A magnetist who pulls foes together, bubbles a target, and crushes armor.', 'Vacuum', 'Bullet jumps pull nearby pickups to Mag, and her shards orbit her as extra blades.', 280, 555, 105, 190, '#5b7cfa'),
(35, 'Mesa', 'mesa', 'warframe', NULL, 'A gunslinger whose exalted pistols clear a line of sight.', 'Gunslinger', 'Mesa aims and reloads sidearms faster, and she gains health when no melee weapon is equipped.', 465, 280, 105, 150, '#e0a15a'),
(36, 'Mirage', 'mirage', 'warframe', NULL, 'An illusionist whose clones copy her weapons and whose light changes her power.', 'Acrobat', 'Slides and bullet jumps make Mirage harder to hit and briefly raise her damage.', 300, 300, 105, 225, '#f2a7c3'),
(37, 'Nekros', 'nekros', 'warframe', NULL, 'A grave binder who terrifies the living and raises the dead.', 'Death Leech', 'Nearby deaths restore a little of Nekros''s health.', 370, 335, 105, 150, '#8f7a9a'),
(38, 'Nezha', 'nezha', 'warframe', NULL, 'A swift guardian who leaves fire in his wake and rings himself in a warding halo.', 'Frictionless', 'Nezha slides farther and faster than other Warframes.', 465, 185, 200, 225, '#e23b3b'),
(39, 'Nidus', 'nidus', 'warframe', NULL, 'An infested host who stacks mutation and spends it to cheat death.', 'Mutation', 'Hitting enemies with his kit builds mutation. Stacks make him stronger and can save him from death.', 775, 0, 450, 150, '#a8b84e'),
(40, 'Nokko', 'nokko', 'warframe', NULL, 'A mushroom sprinter who lulls foes, feeds the squad, and bounces a spore across the room.', 'Fungal Spread', 'His mushrooms invigorate each other, so one cast makes the rest pulse faster.', 250, 400, 135, 180, '#d98a3a'),
(41, 'Nova', 'nova', 'warframe', NULL, 'An antimatter caster who slows a room or speeds it into collapse.', 'Antimatter', 'Fast movement knocks nearby enemies away, and her particles orbit until they find a target.', 370, 280, 105, 225, '#f0d85a'),
(42, 'Nyx', 'nyx', 'warframe', NULL, 'A psychic who turns enemies against each other and folds their damage into a blast.', 'Psychic Pressure', 'Enemies under her control spread confusion, and bolts stolen from them bolster Nyx.', 370, 370, 105, 225, '#6a4c93'),
(43, 'Oberon', 'oberon', 'warframe', NULL, 'A paladin who hallows the ground, renews allies, and smites armor off a crowd.', 'Companion''s Grace', 'His companion is tougher, and hallowed ground protects the squad from status.', 465, 370, 385, 225, '#c4a35a'),
(44, 'Octavia', 'octavia', 'warframe', NULL, 'A musician whose mallet draws fire and whose beat rewards the squad for playing along.', 'Inspiration', 'Allies who jump, crouch, shoot, and melee on her beat gain matching buffs.', 370, 280, 160, 225, '#c9a0dc'),
(45, 'Oraxia', 'oraxia', 'warframe', NULL, 'A spider predator who lurks on walls, webs prey, and walks on silken legs.', 'Predator''s Lurk', 'Latching onto a wall turns Oraxia invisible for a short time.', 675, 225, 125, 200, '#8a3d5c'),
(46, 'Protea', 'protea', 'warframe', NULL, 'A time engineer who lays turrets, supplies, and a rewind that undoes a bad moment.', 'Temporal Save', 'If she would fall while her anchor is ready, she rewinds instead of dying.', 370, 555, 135, 225, '#e39b4a'),
(47, 'Qorvex', 'qorvex', 'warframe', NULL, 'A concrete warden who walls off radiation and crushes a lane with a blast.', 'Concrete Hide', 'Qorvex and nearby allies resist status effects.', 700, 300, 875, 200, '#d1a15a'),
(48, 'Revenant', 'revenant', 'warframe', NULL, 'An eidolon host who enthralls foes and dances behind mesmer charges.', 'Mesmer Shield', 'Damage that would break his shields can turn into Mesmer Skin charges instead.', 370, 735, 135, 190, '#8a9148'),
(49, 'Rhino', 'rhino', 'warframe', NULL, 'A heavy charger who irons his skin, roars a damage buff, and stomps the room.', 'Heavy Landing', 'Hard landings create a shockwave. Iron Skin also grows if he is hit while it forms.', 370, 555, 240, 150, '#b7b7b7'),
(50, 'Saryn', 'saryn', 'warframe', NULL, 'A plague bearer whose spores spread as enemies die.', 'Lingering Toxin', 'Status effects on poisoned enemies last longer, and spores jump to new hosts.', 465, 370, 240, 225, '#9b4d8a'),
(51, 'Sevagoth', 'sevagoth', 'warframe', NULL, 'A reaper whose shadow can take over when his body falls.', 'Shadow', 'Fatal damage sends Sevagoth into his shadow form so he can keep fighting and revive.', 370, 335, 160, 190, '#4a5a70'),
(52, 'Sirius & Orion', 'sirius-orion', 'warframe', NULL, 'Two rival fighters in one Warframe. Tap to cast with the active brother, or hold to swap and cast the other.', 'Constellation', 'Casts build colored stars. Matching a star to the next blast hits harder, and only two stars of one color can form in a row.', 575, 455, 160, 250, '#7eb6ff'),
(53, 'Styanax', 'styanax', 'warframe', NULL, 'A spear commander who rallies shields and ends a fight with a volley.', 'Squad Shields', 'His commands restore shields for Styanax and nearby allies.', 370, 925, 265, 225, '#e6c36a'),
(54, 'Temple', 'temple', 'warframe', NULL, 'A stage performer who times casts to a backbeat and finishes on an exalted guitar.', 'Backbeat', 'Casting on the beat extends the next lick and makes Ripper''s Wail hit hotter.', 505, 325, 325, 215, '#ff5a3c'),
(55, 'Titania', 'titania', 'warframe', NULL, 'A razor-winged fairy who buffs from tribute and fights in a tiny exalted form.', 'Dust Trail', 'Bullet jumps leave a breeze that helps nearby allies, and her companion hits harder.', 370, 370, 105, 225, '#f2c1d6'),
(56, 'Trinity', 'trinity', 'warframe', NULL, 'A field medic who links to allies and turns enemies into wells of life and energy.', 'Wellspring', 'Orbs restore a little health, energy, and shields together when Trinity picks them up.', 370, 370, 105, 225, '#6ec8b8'),
(57, 'Uriel', 'uriel', 'warframe', NULL, 'A condemned devil who commands three demons and spends them as living spells.', 'Legion', 'Three demons unlock as Uriel ranks his abilities, and their power shows on his kit.', 666, 666, 105, 150, '#ff6a2a'),
(58, 'Valkyr', 'valkyr', 'warframe', NULL, 'A berserker who swings into melee range and unleashes claws.', 'Rage', 'Valkyr resists knockdown, and she recovers faster when she is downed.', 750, 185, 855, 150, '#d9d9de'),
(59, 'Vauban', 'vauban', 'warframe', NULL, 'An engineer who mines a room, cages enemies, and calls an orbital strike.', 'Engineer', 'Vauban carries extra capacity for his devices, and trapped enemies take more damage.', 370, 280, 160, 225, '#d7a441'),
(60, 'Volt', 'volt', 'warframe', NULL, 'An electrician who shocks, speeds the squad, and blocks fire with a live shield.', 'Static Charge', 'Moving builds electricity that adds to his next attack.', 370, 555, 105, 150, '#f2d84a'),
(61, 'Voruna', 'voruna', 'warframe', NULL, 'A pack hunter. Each wolf has a tap attack and a hold passive.', 'Wolf Pack', 'Holding an ability lets that wolf guard Voruna with a different passive.', 555, 370, 200, 150, '#c47a4a'),
(62, 'Wisp', 'wisp', 'warframe', NULL, 'A willow spirit who leaves reservoirs of health, speed, and shock for the squad.', 'Airborne', 'Wisp is invisible while she is in the air.', 370, 280, 185, 300, '#f3e2a0'),
(63, 'Wukong', 'wukong', 'warframe', NULL, 'A monkey king who fights beside a clone and survives a fatal hit as cloud.', 'Undying Cloud', 'A killing blow turns him to cloud instead of downing him, then the trick must recharge.', 555, 370, 265, 180, '#e6b15a'),
(64, 'Xaku', 'xaku', 'warframe', NULL, 'A broken trio who steal enemy guns and pause the room in void time.', 'Evasion', 'Xaku''s loose pieces dodge a portion of incoming hits.', 359, 329, 146, 230, '#b7a6d9'),
(65, 'Yareli', 'yareli', 'warframe', NULL, 'A board rider who snares enemies and fights from Merulina.', 'Merulina Bond', 'Riding Merulina raises her secondary-weapon critical chance.', 370, 555, 105, 300, '#6ec4ef'),
(66, 'Zephyr', 'zephyr', 'warframe', NULL, 'A wind rider who stays airborne, deflects bullets, and gathers enemies into tornadoes.', 'Airtime', 'Zephyr hovers longer and is harder to hit while she is in the air.', 555, 555, 105, 150, '#a7d4ea'),
(67, 'Narin', 'narin', 'warframe', NULL, 'An ice dancer who builds an Ice meter, then spends it on a sword dance.', 'Cold Harvest', 'Cold status on enemies can leave a pickup that adds cold damage to her guns and her abilities.', 370, 650, 165, 250, '#c5e6f5'),
